-- Check rental counts per customer
SELECT MIN(total_rentals) AS min_rentals, MAX(total_rentals) AS max_rentals, AVG(total_rentals) AS avg_rentals
FROM (
    SELECT customer_id, COUNT(*) AS total_rentals
    FROM rental
    GROUP BY customer_id
);
